<template>
    <ol class="timeline" :class="{ 'timeline-simple': simple }" role="list">
        <li
            v-for="(entry, index) in entries"
            :key="entry.id"
            :class="{ 'timeline-inverted': simple || index % 2 === 0 }"
        >
            <div class="timeline-badge" :class="entry.color || 'primary'" aria-hidden="true">
                <i v-if="entry.icon" class="material-icons">{{ entry.icon }}</i>
            </div>
            <article class="timeline-panel">
                <h4 class="timeline-heading">
                    <span class="badge rounded-pill" :class="`badge-${entry.color || 'primary'}`">{{ entry.title }}</span>
                </h4>
                <div class="timeline-body">
                    <slot name="body" :entry="entry">
                        <p v-for="(paragraph, paragraphIndex) in entry.paragraphs" :key="paragraphIndex">
                            {{ paragraph }}
                        </p>
                    </slot>
                </div>
                <p v-if="entry.timestamp" class="timeline-meta h6">
                    <i class="material-icons" aria-hidden="true">schedule</i>
                    {{ entry.timestamp }}
                </p>
                <slot name="footer" :entry="entry" />
            </article>
        </li>
    </ol>
</template>

<script>
export default {
    name: 'Timeline',
    props: {
        entries: { type: Array, required: true },
        simple: { type: Boolean, default: false },
    },
};
</script>
